const listAccessTokens = `-- name: ListAccessTokens :many
SELECT id, organization_id, user_id, name, prefix, secret_hash, scopes, source, subject, created_at, expires_at, last_used_at, revoked_at FROM access_tokens
 WHERE organization_id = $1
   AND ($2::uuid IS NULL OR user_id = $2::uuid)
   AND (created_at, id) > ($3::timestamptz, $4::uuid)
 ORDER BY created_at, id
 LIMIT $5
`

type ListAccessTokensParams struct {
	OrganizationID pgtype.UUID
	UserID         pgtype.UUID
	AfterTime      pgtype.Timestamptz
	AfterID        pgtype.UUID
	PageSize       int32
}

func (q *Queries) ListAccessTokens(ctx context.Context, arg ListAccessTokensParams) ([]AccessToken, error) {
	rows, err := q.db.Query(ctx, listAccessTokens,
		arg.OrganizationID,
		arg.UserID,
		arg.AfterTime,
		arg.AfterID,
		arg.PageSize,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []AccessToken{}
	for rows.Next() {
		var i AccessToken
		if err := rows.Scan(
			&i.ID,
			&i.OrganizationID,
			&i.UserID,
			&i.Name,
			&i.Prefix,
			&i.SecretHash,
			&i.Scopes,
			&i.Source,
			&i.Subject,
			&i.CreatedAt,
			&i.ExpiresAt,
			&i.LastUsedAt,
			&i.RevokedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

